{"file_path":"src/count.js","content":"/**
 * Runs the instant-runoff count. Returns
 * `{ rounds: [{ counts: Map<string, BigInt>, exhausted: BigInt, eliminated: string|null }], winner: string|null }`.
 * `counts` holds an entry for every candidate still continuing at that round.
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = []
  let winner = null

  for (;;) {
    const counts = new Map()
    for (const name of continuing) counts.set(name, 0n)
    let exhausted = 0n

    for (const { count, names } of ballots) {
      const choice = names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += count
      } else {
        counts.set(choice, counts.get(choice) + count)
      }
    }

    let activeTotal = 0n
    for (const value of counts.values()) activeTotal += value

    const round = { counts, exhausted, eliminated: null }
    history.push(round)

    if (activeTotal === 0n) {
      winner = null
      break
    }

    const majorityWinner = [...counts.entries()].find(([, value]) => value * 2n > activeTotal)
    if (majorityWinner) {
      winner = majorityWinner[0]
      break
    }

    let minVal = null
    for (const value of counts.values()) {
      if (minVal === null || value < minVal) minVal = value
    }
    let tied = [...counts.entries()].filter(([, value]) => value === minVal).map(([name]) => name)

    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history)
    round.eliminated = eliminated
    continuing.delete(eliminated)
  }

  return { rounds: history, winner }
}

function breakTie(initialTied, history) {
  let tied = initialTied
  for (;;) {
    let narrowed = null
    for (const round of history) {
      const values = tied.map((name) => round.counts.get(name))
      const allEqual = values.every((v) => v === values[0])
      if (!allEqual) {
        let minVal = values[0]
        for (const v of values) if (v < minVal) minVal = v
        narrowed = tied.filter((name) => round.counts.get(name) === minVal)
        break
      }
    }
    if (narrowed === null) break
    tied = narrowed
    if (tied.length === 1) break
  }
  if (tied.length === 1) return tied[0]
  return tied.slice().sort().at(-1)
}
"}

