      const values = tied.map((name) => round.counts.get(name))
      const allEqual = values.every((v) => v === values[0])
      if (!allEqual) {
        let minVal = values[0]
        for (const v of values) if (v < minVal) minVal = v
        narrowed = tied.filter((name) => round.counts.get(name) === minVal)
        break
      }
    }
    if (narrowed === null) break
    tied = narrowed
    if (tied.length === 1) break
  }
  if (tied.length === 1) return tied[0]
  return tied.slice().sort().at(-1)
}
"}

