  return [...counts.entries()].sort((a, b) => {
    if (a[1] !== b[1]) return a[1] > b[1] ? -1 : 1
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
}

function winnerLine(winner) {
  return winner === null ? 'no winner\n' : `winner ${winner}\n`
}

export function formatRounds(result) {
  let out = ''
  result.rounds.forEach((round, index) => {
    const entries = sortedEntries(round.counts)
    const parts = entries.map(([name, value]) => `${name}=${value}`)
    out += `round ${index + 1}: ${parts.join(' ')} exhausted=${round.exhausted}\n`
    if (round.eliminated !== null) {
      out += `eliminated ${round.eliminated}\n`
    }
  })
  out += winnerLine(result.winner)
  return out
}

export function formatTally(result) {
  return `rounds ${result.rounds.length}\n${winnerLine(result.winner)}`
}
